import math

def Phi(z):
    """Standard normal cdf."""
    return 0.5 * (1 + math.erf(z / math.sqrt(2)))

def exact_tail(n, p, k):
    """P(X >= k) for X ~ Bin(n, p), summed exactly."""
    return sum(math.comb(n, j) * p**j * (1 - p)**(n - j)
               for j in range(k, n + 1))

def normal_tail(n, p, k):
    """P(X >= k) by the normal, with continuity correction."""
    mu = n * p
    sd = math.sqrt(n * p * (1 - p))
    return 1 - Phi((k - 0.5 - mu) / sd)
